mapper.select:
select l.id, l.aftersales_id, l.action, l.from_status, l.to_status, l.operator_user_id, l.operator_role, l.note, l.visible_to_consumer, l.created_at, u.display_name as operator_name from aftersales_action_log l join app_user u on u.id = l.operator_user_id where l.aftersales_id = #{aftersalesId}
and l.visible_to_consumer = 1
order by l.created_at, l.id
